import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { openDb } from '../src/db.js';

function tempDbPath(t) {
  const dir = mkdtempSync(join(tmpdir(), 'bookmark-box-'));
  t.after(() => rmSync(dir, { recursive: true, force: true }));
  return join(dir, 'nested', 'bookmarks.db');
}

test('data written to disk survives closing and reopening the database', (t) => {
  const path = tempDbPath(t);

  const first = openDb(path);
  const { lastInsertRowid } = first
    .prepare('INSERT INTO bookmarks (url, title) VALUES (?, ?)')
    .run('https://nodejs.org', 'Node.js');
  first.prepare('INSERT INTO bookmark_tags (bookmark_id, tag) VALUES (?, ?)').run(lastInsertRowid, 'js');
  first.close();

  const second = openDb(path);
  t.after(() => second.close());
  const row = second.prepare('SELECT url, title FROM bookmarks WHERE id = ?').get(lastInsertRowid);
  assert.deepEqual({ ...row }, { url: 'https://nodejs.org', title: 'Node.js' });
  const tags = second.prepare('SELECT tag FROM bookmark_tags WHERE bookmark_id = ?').all(lastInsertRowid);
  assert.deepEqual(tags.map((r) => r.tag), ['js']);
});

test('deleting a bookmark removes its tags', (t) => {
  const db = openDb(tempDbPath(t));
  t.after(() => db.close());
  const { lastInsertRowid: id } = db
    .prepare('INSERT INTO bookmarks (url, title) VALUES (?, ?)')
    .run('https://example.com', 'Example');
  db.prepare('INSERT INTO bookmark_tags (bookmark_id, tag) VALUES (?, ?)').run(id, 'demo');

  db.prepare('DELETE FROM bookmarks WHERE id = ?').run(id);

  const { n } = db.prepare('SELECT COUNT(*) AS n FROM bookmark_tags').get();
  assert.equal(n, 0);
});

