/**
 * Storage: a single SQLite file opened with the built-in node:sqlite module.
 *
 * Schema
 *   bookmarks      (id, url, title, created_at)
 *   bookmark_tags  (bookmark_id → bookmarks.id ON DELETE CASCADE, tag)
 * Tags live in their own table so "list by tag" is an indexed lookup and
 * deleting a bookmark cleans up its tags automatically.
 */
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

const SCHEMA = `
  CREATE TABLE IF NOT EXISTS bookmarks (
    id         INTEGER PRIMARY KEY AUTOINCREMENT,
    url        TEXT    NOT NULL,
    title      TEXT    NOT NULL,
    created_at TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
  );
  CREATE TABLE IF NOT EXISTS bookmark_tags (
    bookmark_id INTEGER NOT NULL REFERENCES bookmarks(id) ON DELETE CASCADE,
    tag         TEXT    NOT NULL,
    PRIMARY KEY (bookmark_id, tag)
  );
  CREATE INDEX IF NOT EXISTS bookmark_tags_by_tag ON bookmark_tags(tag);
`;

/**
 * Open (creating if needed) the database file at `path` and apply the schema.
 * Pass ':memory:' for a throwaway database.
 * @param {string} path
 * @returns {DatabaseSync}
 */
export function openDb(path) {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  db.exec('PRAGMA foreign_keys = ON; PRAGMA journal_mode = WAL;');
  db.exec(SCHEMA);
  return db;
}

