/**
 * Entry point: open the database file and start the HTTP server.
 *   PORT        — port to listen on (default 3000)
 *   BOOKMARKS_DB — path to the SQLite file (default data/bookmarks.db)
 */
import { openDb } from './db.js';
import { createApp } from './server.js';

const port = Number(process.env.PORT ?? 3000);
const dbPath = process.env.BOOKMARKS_DB ?? 'data/bookmarks.db';

const db = openDb(dbPath);
const server = createApp();

server.listen(port, () => {
  console.log(`Bookmark Box listening on http://localhost:${port} (db: ${dbPath})`);
});

function shutdown() {
  server.close(() => {
    db.close();
    process.exit(0);
  });
}
process.on('SIGINT', shutdown);
process.on('SIGTERM', shutdown);

